private IEnumerator ResponseCoroutine_CreateUser()
{
	SetDelayDialog(sw: true);
	for (int count = 0; count < m_RetryLimit; count++)
	{
		WWWForm form = new WWWForm();
		Dictionary<string, string> req = new Dictionary<string, string>
		{
			{ "ver", "2.4.0" },
			{
				"retry",
				RetryCount.ToString()
			},
			{ "user_name", m_PlayerName }
		};
		string key = Guid.NewGuid().ToString();
		req.Add("platform", "1");
		req.Add("uuid", key);
		req.Add("model_name", SystemInfo.deviceModel);
		req.Add("unit_no", m_FirstUnitNo.ToString());
		string reqJson = JsonMapper.ToJson(req);
		form.AddField("request", reqJson);
		Hashtable headers = form.headers;
		headers["User-Agent"] = "RTD-Client-App";
		headers["Accept-Encoding"] = "gzip, deflate";
		WWW www = null;
		try
		{
			www = new WWW(m_Address, form.data, headers);
		}
		catch (Exception ex)
		{
			DebugLogger.LogWarning(">NetworkError : " + ex.ToString());
		}
		m_SessionID = null;
		yield return www;
		if (www.error == null)
		{
			byte[] DecoBuffer = GZipArchiveCall.CallDecompress(www.bytes);
			Console.WriteLine("******************** Decompression");
			string DecoText = Encoding.UTF8.GetString(DecoBuffer);
			DebugLogger.Log("ResponseCoroutine_CreateUser {" + DecoText + "} Len:" + DecoText.Length);
			ChangeReturnValue(DecoText, www.error);
		}
		else
		{
			DebugLogger.LogWarning(">WWW_Error: " + www.error);
			ChangeReturnValue(www.text, www.error);
		}
		if (m_LastError == PROC_CODE.RETRY)
		{
			continue;
		}
		if (m_LastError == PROC_CODE.OK)
		{
			SaveDataManager.m_UUID = key;
			break;
		}
		if (m_LastError == PROC_CODE.INVALID_VERSION)
		{
			while (true)
			{
				Dialog dialog = Dialog.OpenNetError("ER_VER_ANDROID", "BTN_OK");
				while (dialog.button == DlgButton.None)
				{
					yield return new WaitForSeconds(0.01f);
				}
				Application.OpenURL(Singleton<ResidentManager>.Instance.GetAppAddress());
			}
		}
		if (m_LastError == PROC_CODE.SERVER_MENTENANCE)
		{
			Dialog dialog2 = Dialog.OpenNetError("ER_SERVER", "BTN_RECON");
			while (dialog2.button == DlgButton.None)
			{
				yield return new WaitForSeconds(0.01f);
			}
		}
		else if (m_LastError == PROC_CODE.NG_NAME)
		{
			break;
		}
	}
	SetDelayDialog(sw: false);
	m_SeqEnd = true;
}

