private static void CreateRequest_GetMasterDBHash()
{
	m_DelayDialogText = GameText.Get("LD_LEVEL");
	RequestGetMaster requestGetMaster = new RequestGetMaster(RetryCount);
	requestGetMaster.compare_hash_only = m_MasterHashOnly;
	requestGetMaster.get_data_list = new RequestGetMaster.ClientMaster[DownLoadMasterDB.m_masters.Length];
	for (int i = 0; i < DownLoadMasterDB.m_masters.Length; i++)
	{
		requestGetMaster.get_data_list[i] = new RequestGetMaster.ClientMaster();
		requestGetMaster.get_data_list[i].type = (int)DownLoadMasterDB.m_masters[i];
		requestGetMaster.get_data_list[i].hash = SaveDataManager.GetMasterHash(DownLoadMasterDB.m_masters[i]);
	}
	m_ReqJson = JsonMapper.ToJson(requestGetMaster);
}

