		requestOrderQuest.hashes.Add(string.Empty + 20, SaveDataManager.GetMasterHash(MASTERDB.ENEMY_UNIT_MASTER).ToString());
		requestOrderQuest.hashes.Add(string.Empty + 10, SaveDataManager.GetMasterHash(MASTERDB.UNIT_MASTER).ToString());
		requestOrderQuest.hashes.Add(string.Empty + 11, SaveDataManager.GetMasterHash(MASTERDB.PARTY_SKILL_MASTER).ToString());
		requestOrderQuest.hashes.Add(string.Empty + 12, SaveDataManager.GetMasterHash(MASTERDB.PARTY_SKILL_RANK_MASTER).ToString());
