		requestOrderQuest.hashes.Add(string.Empty + 90, SaveDataManager.GetMasterHash(MASTERDB.GLOBAL_PARAM_MASTER).ToString());
		requestOrderQuest.level_data_hash = SaveDataManager.GetLevelDataMasterHash(m_QuestID).ToString();
		requestOrderQuest.hashes.Add(string.Empty + 16, SaveDataManager.GetMasterHash(MASTERDB.PANEL_SKILL_MASTER).ToString());
		requestOrderQuest.hashes.Add(string.Empty + 17, SaveDataManager.GetMasterHash(MASTERDB.PANEL_SKILL_RANK_MASTER).ToString());
	}
	else
	{
		requestOrderQuest.hashes.Add(string.Empty + 30, "0");
		requestOrderQuest.hashes.Add(string.Empty + 31, "0");
		requestOrderQuest.hashes.Add(string.Empty + 21, "0");
		requestOrderQuest.hashes.Add(string.Empty + 20, "0");
		requestOrderQuest.hashes.Add(string.Empty + 10, "0");
		requestOrderQuest.hashes.Add(string.Empty + 11, "0");
		requestOrderQuest.hashes.Add(string.Empty + 12, "0");
		requestOrderQuest.hashes.Add(string.Empty + 13, "0");
		requestOrderQuest.hashes.Add(string.Empty + 14, "0");
		requestOrderQuest.hashes.Add(string.Empty + 32, "0");
		requestOrderQuest.hashes.Add(string.Empty + 33, "0");
		requestOrderQuest.hashes.Add(string.Empty + 90, "0");
		requestOrderQuest.level_data_hash = "0";
		requestOrderQuest.hashes.Add(string.Empty + 16, "0");
		requestOrderQuest.hashes.Add(string.Empty + 17, "0");
	}
	requestOrderQuest.token = m_Token;
	m_ReqJson = JsonMapper.ToJson(requestOrderQuest);
}

