private static void CreateRequest_QuestClear()
{
	m_DelayDialogText = GameText.Get("LD_UPDATE");
	RequestClearQuest requestClearQuest = new RequestClearQuest(RetryCount);
	requestClearQuest.exp = ClientData.m_GotExp;
	requestClearQuest.game_money = ClientData.m_GotMoney;
	requestClearQuest.quest_id = (uint)ClientData.m_SelectedQuest.id;
	float f = Mathf.Pow(ClientData.m_GotSoul * ClientData.m_SelectedQuest.reward_soul, 0.65f);
	f = Mathf.Floor(f);
	requestClearQuest.yorisiro_exp = (uint)f * 15;
	DebugLogger.Log(">Total  / " + requestClearQuest.yorisiro_exp);
	requestClearQuest.units = new List<RequestClearQuest.GotBook>();
	if (ClientData.m_Books != null)
	{
		for (int i = 0; i < ClientData.m_Books.Count; i++)
		{
			RequestClearQuest.GotBook gotBook = new RequestClearQuest.GotBook();
			gotBook.unit_id = ClientData.m_Books[i].id;
			gotBook.level = ClientData.m_Books[i].level;
			requestClearQuest.units.Add(gotBook);
		}
	}
	requestClearQuest.challenge_id_list = new List<int>();
	if (ClientData.m_ChallengeID != null)
	{
		for (int j = 0; j < ClientData.m_ChallengeID.Count; j++)
		{
			requestClearQuest.challenge_id_list.Add(ClientData.m_ChallengeID[j]);
		}
	}
	m_ReqJson = JsonMapper.ToJson(requestClearQuest);
}

