public IEnumerator _getLevelDataMasterAll()
{
	Debug.LogWarning("_getLevelDataMasterAll");
	while (!m_SeqEnd)
	{
		yield return new WaitForSeconds(0.01f);
	}
	m_SeqEnd = false;
	m_CreateRequestJsonFunc = CreateRequest_GetLevelDataMasterAll;
	SetAddress(PHP.ADRS_GET_LEVEL_DATA_MASTER);
	yield return StartCoroutine(Singleton<ComManager>.Instance.SequenceCoroutine_Common());
	m_SeqEnd = true;
	if (m_LevelDataMasterTmp == null)
	{
		yield break;
	}
	for (int i = 0; i < m_LevelDataMasterTmp.Length; i++)
	{
		if (m_LevelMasterStatic)
		{
			string fileName = Application.dataPath + "/Resources/LevelData/" + m_LevelDataMasterTmp[i].level_data_id + ".txt";
			StreamWriter writer = new StreamWriter(fileName);
			string temp = JsonMapper.ToJson(m_LevelDataMasterTmp[i]);
			writer.WriteLine(temp);
			writer.Close();
			writer = null;
		}
		float passed_time = Time.time;
		SaveDataManager.SaveLevelDataMasterDB(m_LevelDataMasterTmp[i]);
		Debug.LogWarning(">LevelDataMaster IO : " + (Time.time - passed_time));
		yield return new WaitForSeconds(0.01f);
	}
	m_LevelDataMasterTmp = null;
}

