private static void CreateRequest_QuestClear2()
{
	m_DelayDialogText = GameText.Get("LD_UPDATE");
	RequestClearQuest2 requestClearQuest = new RequestClearQuest2(RetryCount);
	requestClearQuest.list = new RequestClearQuest2.Quest[ClientData.m_QuestResult.Count];
	for (int i = 0; i < ClientData.m_QuestResult.Count; i++)
	{
		RequestClearQuest2.Quest quest = new RequestClearQuest2.Quest();
		QuestMaster[] questMaster = ClientData.GetQuestMaster();
		QuestMaster questMaster2 = null;
		for (int j = 0; j < questMaster.Length; j++)
		{
			if (questMaster[j].id == ClientData.m_QuestResult[i].m_QuestID)
			{
				questMaster2 = questMaster[j];
				break;
			}
		}
		quest.exp = ClientData.m_QuestResult[i].m_GetExp;
		quest.game_money = ClientData.m_QuestResult[i].m_GetMoney;
		quest.quest_id = (uint)ClientData.m_QuestResult[i].m_QuestID;
		float f = Mathf.Pow(ClientData.m_QuestResult[i].m_PartySoul * questMaster2.reward_soul, 0.65f);
		f = Mathf.Floor(f);
		quest.yorisiro_exp = (uint)f * 15;
		DebugLogger.Log(">Total  / " + quest.yorisiro_exp);
		quest.units = new List<RequestClearQuest2.Quest.GotBook>(5);
		if (ClientData.m_QuestResult[i].m_Books != null)
		{
			for (int k = 0; k < ClientData.m_QuestResult[i].m_Books.Count; k++)
			{
				RequestClearQuest2.Quest.GotBook gotBook = new RequestClearQuest2.Quest.GotBook();
				gotBook.unit_id = ClientData.m_QuestResult[i].m_Books[k].id;
				gotBook.level = ClientData.m_QuestResult[i].m_Books[k].level;
				quest.units.Add(gotBook);
			}
		}
		quest.challenge_id_list = new List<int>(8);
		if (ClientData.m_QuestResult[i].m_ChallengeID != null)
		{
			for (int l = 0; l < ClientData.m_QuestResult[i].m_ChallengeID.Count; l++)
			{
				quest.challenge_id_list.Add(ClientData.m_QuestResult[i].m_ChallengeID[l]);
			}
		}
		quest.sp_event_point = ClientData.m_QuestResult[i].m_GetEventPoint;
		quest.attribute_exp_none = ClientData.m_QuestResult[i].m_AttributeExp[0];
		quest.attribute_exp_fire = ClientData.m_QuestResult[i].m_AttributeExp[3];
		quest.attribute_exp_water = ClientData.m_QuestResult[i].m_AttributeExp[4];
		quest.attribute_exp_shine = ClientData.m_QuestResult[i].m_AttributeExp[1];
		quest.attribute_exp_dark = ClientData.m_QuestResult[i].m_AttributeExp[2];
		requestClearQuest.list[i] = quest;
	}
	if (ClientData.m_UnitParty != null)
	{
		for (int m = 0; m < ClientData.m_uBattleUnitInstanceIds.Length; m++)
		{
			requestClearQuest.party_instance_id[m] = ClientData.m_uBattleUnitInstanceIds[m];
		}
	}
	m_ReqJson = JsonMapper.ToJson(requestClearQuest);
}

