	public List<SpEventPointList> sp_event_point_list = new List<SpEventPointList>();

	public int payment_total;

	public byte[] bonus_flags;

	public UnitCollection GetCollectData(uint serch_id)
	{
		UnitCollection result = null;
		if (unit_collection != null)
		{
			for (int i = 0; i < unit_collection.Length; i++)
			{
				if (unit_collection[i].unit_id == serch_id)
				{
					result = unit_collection[i];
					break;
				}
			}
			DebugLogger.LogWarning(">UnitCollection is Nothig.");
		}
		else
		{
			DebugLogger.LogWarning(">UnitCollection is Null.");
		}
		return result;
	}

	public int GetTotalOpenCollectCount()
	{
		int num = 0;
		UnitCollection[] array = unit_collection;
		foreach (UnitCollection unitCollection in array)
		{
			if (unitCollection.status != 0)
			{
				num++;
			}
		}
		return num;
	}

	public bool GetQuesutChallengeFlag(int quest_ID, int challenge_ID)
	{
		if (quest_challenge_state == null)
		{
			return false;
		}
		for (int i = 0; i < quest_challenge_state.Count; i++)
		{
			if (quest_challenge_state[i].quest_id == quest_ID && quest_challenge_state[i].challenge_id == challenge_ID)
			{
				if (quest_challenge_state[i].state == 1)
				{
					return true;
				}
				return false;
			}
		}
		return false;
	}

	public void SetQuesutChallengeFlag(int quest_ID, int challenge_ID)
	{
		if (quest_challenge_state == null)
		{
			return;
		}
		for (int i = 0; i < quest_challenge_state.Count; i++)
		{
			if (quest_challenge_state[i].quest_id == quest_ID && quest_challenge_state[i].challenge_id == challenge_ID)
			{
				quest_challenge_state[i].state = 1;
				return;
			}
		}
		QuestChallengeState questChallengeState = new QuestChallengeState();
		questChallengeState.quest_id = quest_ID;
		questChallengeState.challenge_id = challenge_ID;
		questChallengeState.state = 1;
		quest_challenge_state.Add(questChallengeState);
	}

	public bool GetChallengeRewardPresentFlag(int rewardID)
	{
		if (quest_challenge_reward_state == null)
		{
			return false;
		}
		for (int i = 0; i < quest_challenge_reward_state.Count; i++)
		{
			if (quest_challenge_reward_state[i].reward_id == rewardID)
			{
				if (quest_challenge_reward_state[i].state == 1)
				{
					return true;
				}
				return false;
			}
		}
		return false;
	}

	public void SetQuestChallengeRewardFlag(int reward_ID)
	{
		if (quest_challenge_reward_state == null)
		{
			return;
		}
		for (int i = 0; i < quest_challenge_reward_state.Count; i++)
		{
			if (quest_challenge_reward_state[i].reward_id == reward_ID)
			{
				quest_challenge_reward_state[i].state = 1;
				return;
			}
		}
		QuestChallengeRewardState questChallengeRewardState = new QuestChallengeRewardState();
		questChallengeRewardState.reward_id = reward_ID;
		questChallengeRewardState.state = 1;
		quest_challenge_reward_state.Add(questChallengeRewardState);
	}

	public bool GetBonusFlags(int bit)
	{
		bool result = false;
		int num = ((bonus_flags != null) ? bonus_flags.Length : 0);
		int num2 = bit / 8;
		if (num > 0 && num2 < num)
		{
			result = (bonus_flags[num2] & (1 << bit % 8)) != 0;
		}
		return result;
	}
}

