using System;
using MasterDataRTD;
using UnityEngine;

namespace CommunicationRTD;

[Serializable]
public class ResponseBuyGachaSpecial : ResponseCommon
{
	public class Result : ResponseGachaCommon
	{
		public GachaGetUnits[] gacha_units;

		public Result()
		{
			gacha_units = null;
		}
	}

	public class GachaGetUnit
	{
		public uint kind;

		public ulong instance_id;

		public uint user_id;

		public uint unit_id;

		public int member_id;

		public uint level;

		public uint exp;
	}

	public class GachaGetUnits
	{
		public GachaGetUnit[] gacha_unit;

		public GachaGetUnits()
		{
			gacha_unit = null;
		}
	}

	public Result result;

	public void GetUnitData(out GachaGetUnitDatas[] unitArray)
	{
		int num = result.gacha_units.Length;
		unitArray = new GachaGetUnitDatas[num];
		Debug.Log(">GachaCount : " + num);
		for (int i = 0; i < num; i++)
		{
			int num2 = result.gacha_units[i].gacha_unit.Length;
			Debug.Log(">UnitCount : " + num2);
			unitArray[i] = new GachaGetUnitDatas();
			unitArray[i].m_GetUnits = new UnitData[num2];
			for (int j = 0; j < num2; j++)
			{
				if (result.gacha_units[i].gacha_unit[j].kind == 1)
				{
					unitArray[i].m_GetUnits[j] = null;
					continue;
				}
				unitArray[i].m_GetUnits[j] = new UnitData();
				unitArray[i].m_GetUnits[j].instance_id = result.gacha_units[i].gacha_unit[j].instance_id;
				unitArray[i].m_GetUnits[j].user_id = result.gacha_units[i].gacha_unit[j].user_id;
				unitArray[i].m_GetUnits[j].unit_id = (int)result.gacha_units[i].gacha_unit[j].unit_id;
				unitArray[i].m_GetUnits[j].member_id = result.gacha_units[i].gacha_unit[j].member_id;
				unitArray[i].m_GetUnits[j].level = (int)result.gacha_units[i].gacha_unit[j].level;
				unitArray[i].m_GetUnits[j].exp = (int)result.gacha_units[i].gacha_unit[j].exp;
				unitArray[i].m_GetUnits[j].bonus_life = 0;
				unitArray[i].m_GetUnits[j].bonus_heal = 0;
				unitArray[i].m_GetUnits[j].bonus_attack = 0;
				unitArray[i].m_GetUnits[j].bonus_limit = 0;
				unitArray[i].m_GetUnits[j].SetMasterRecord();
				DebugLogger.Log(">GetUnit_" + j + " : " + unitArray[i].m_GetUnits[j].master.name);
				UnitInfo unitInfo = new UnitInfo();
				unitInfo.instance_id = unitArray[i].m_GetUnits[j].instance_id;
				unitInfo.unit_id = unitArray[i].m_GetUnits[j].unit_id;
				unitInfo.member_id = unitArray[i].m_GetUnits[j].member_id;
				unitInfo.level = unitArray[i].m_GetUnits[j].level;
				unitInfo.exp = unitArray[i].m_GetUnits[j].exp;
				unitInfo.bonus_limit = 0;
				unitInfo.bonus_life = 0;
				unitInfo.bonus_attack = 0;
				unitInfo.bonus_heal = 0;
				ClientData.AddUnit(unitInfo);
			}
		}
	}
}

