	{
		List<int> list = new List<int>(enemies.Count);
		foreach (int key in enemies.Keys)
		{
			if (enemies[key].enemy_id != 0)
			{
				list.Add(enemies[key].enemy_id);
			}
		}
		int[] result = list.Distinct().ToArray();
		list = null;
		return result;
	}

