using System;
using UnityEngine;

namespace MasterDataRTD;

[Serializable]
public class PartyInfo
{
	public struct Units
	{
		public ulong[] instanceIds;
	}

	public uint active;

	public Units[] party;

	public int ActivePartyNum()
	{
		return (int)active;
	}

	public int PartyNumMax()
	{
		return party.Length;
	}

	public ulong GetLeaderInstanceID()
	{
		return party[active].instanceIds[0];
	}

	public ulong GetActiveInstanceID(int member_num)
	{
		return GetInstanceID(ActivePartyNum(), member_num);
	}

	public int GetActivePartyMemberID(ulong instanceID)
	{
		return GetPartyMemberID(ActivePartyNum(), instanceID);
	}

	public int GetPartyMemberID(int party_num, ulong instanceID)
	{
		int result = -1;
		if (instanceID != 0L && party_num < party.Length)
		{
			for (int i = 0; i < party[party_num].instanceIds.Length; i++)
			{
				if (party[party_num].instanceIds[i] == instanceID)
				{
					result = i;
					break;
				}
			}
		}
		return result;
	}

	public bool IsPartyMember_Negative(ulong instanceID)
	{
		bool flag = false;
		if (instanceID != 0L)
		{
			for (int i = 0; i < party.Length; i++)
			{
				if (i == active)
				{
					continue;
				}
				for (int j = 0; j < party[i].instanceIds.Length; j++)
				{
					if (party[i].instanceIds[j] == instanceID)
					{
						flag = true;
						break;
					}
				}
				if (flag)
				{
					break;
				}
			}
		}
		return flag;
	}

	public bool IsPartyMember_Active(ulong instanceID)
	{
		bool result = false;
		if (instanceID != 0L)
		{
			for (int i = 0; i < party[active].instanceIds.Length; i++)
			{
				if (party[active].instanceIds[i] == instanceID)
				{
					result = true;
					break;
				}
			}
		}
		return result;
	}

	public bool IsSameMainMember(ulong instanceID)
	{
		bool flag = false;
		if (instanceID != 0L)
		{
			for (int i = 0; i < party.Length; i++)
			{
				for (int j = 0; j < 3; j++)
				{
					if (party[i].instanceIds[j] == instanceID)
					{
						flag = true;
						break;
					}
				}
				if (flag)
				{
					break;
				}
			}
		}
		return flag;
	}

	public bool IsSomeSubMember(ulong instansID)
	{
		bool result = false;
		if (instansID != 0L)
		{
			for (int i = 0; i < party.Length; i++)
			{
				if (party[i].instanceIds[3] == instansID || party[i].instanceIds[4] == instansID)
				{
					result = true;
					break;
				}
			}
		}
		return result;
	}

	public int GetSomePartyMemberID(ulong instanceID)
	{
		int num = -1;
		if (instanceID != 0L)
		{
			for (int i = 0; i < party.Length; i++)
			{
				for (int j = 0; j < party[i].instanceIds.Length; j++)
				{
					if (party[i].instanceIds[j] == instanceID)
					{
						num = j;
						break;
					}
				}
				if (num != -1)
				{
					break;
				}
			}
		}
		return num;
	}

	public ulong GetInstanceID(int party_num, int member_num)
	{
		ulong result = 0uL;
		if (party_num < party.Length && member_num < party[party_num].instanceIds.Length)
		{
			result = party[party_num].instanceIds[member_num];
		}
		return result;
	}

	public void SetActivePartyMember(int member_num, ulong instanceID)
	{
		SetPartyMember(ActivePartyNum(), member_num, instanceID);
	}

	public void SetPartyMember(int party_num, int member_num, ulong instanceID)
	{
		int num = -1;
		if (party_num < 0 || party_num >= party.Length || member_num < 0 || member_num >= party[party_num].instanceIds.Length)
		{
			return;
		}
		for (int i = 0; i < party[party_num].instanceIds.Length; i++)
		{
			if (party[party_num].instanceIds[i] == instanceID)
			{
				num = i;
				break;
			}
		}
		if (num >= 0)
		{
			ulong num2 = party[party_num].instanceIds[member_num];
			party[party_num].instanceIds[member_num] = instanceID;
			party[party_num].instanceIds[num] = num2;
			return;
		}
		DebugLogger.Log(">SetPartyMember[" + party_num + " , " + member_num + "]");
		party[party_num].instanceIds[member_num] = instanceID;
	}

	public void SwapMember_AllParty(ulong search_id, ulong swaped_id)
	{
		for (int i = 0; i < party.Length; i++)
		{
			SwapMember(i, search_id, swaped_id);
		}
		for (int j = 0; j < party.Length; j++)
		{
			Debug.Log("< PARTY " + j + ">");
			Debug.Log(party[j].instanceIds[0] + "," + party[j].instanceIds[1] + "," + party[j].instanceIds[2] + "," + party[j].instanceIds[3] + "," + party[j].instanceIds[4]);
		}
	}

	public void SwapMember(int party_num, ulong search_id, ulong swaped_id)
	{
		if (party_num >= party.Length)
		{
			return;
		}
		for (int i = 0; i < party[party_num].instanceIds.Length; i++)
		{
			if (party[party_num].instanceIds[i] == search_id)
			{
				Debug.Log(">Swap[" + party_num + "," + i + "] : " + swaped_id);
				party[party_num].instanceIds[i] = swaped_id;
				break;
			}
		}
	}
}

