	{
		if (ClientData.GetPartySkillMasterLevel(master, level) == 0)
		{
			nm = GameText.Get("NONE");
			txt = " ";
		}
		else
		{
			nm = "?????";
			txt = GameText.Get("SKILL_LEVEL") + ":" + ClientData.GetPartySkillMasterLevel(master, level);
		}
	}

	public void SetActiveSkillText(ref string nm, ref string txt)
	{
		if (ClientData.GetActiveSkillMasterLevel(master, level) == 0)
		{
			nm = GameText.Get("NONE");
			txt = " ";
		}
		else
		{
			nm = "?????";
			txt = GameText.Get("SKILL_LEVEL") + ":" + ClientData.GetActiveSkillMasterLevel(master, level);
		}
