	{
		if (ClientData.GetPanelSkillMasterLevel(master, level) == 0)
		{
			nm = GameText.Get("NONE");
			txt = " ";
		}
		else
		{
			nm = "?????";
			txt = GameText.Get("SKILL_LEVEL") + ":" + ClientData.GetPanelSkillMasterLevel(master, level);
		}
	}

	public bool GetPartySkillNameDesc(ref string nm, ref string txt)
	{
		if (partySkill == null)
		{
			SetPartySkillText(ref nm, ref txt);
			return false;
		}
		nm = partySkill.name;
		txt = partySkill.text;
		if (nm == null || nm.Length == 0)
		{
			SetPartySkillText(ref nm, ref txt);
		}
		if (txt == null || txt.Length == 0)
		{
			SetPartySkillText(ref nm, ref txt);
		}
		return true;
	}

