	{
		if (activeSkill == null)
		{
			SetActiveSkillText(ref nm, ref txt);
			return false;
		}
		nm = activeSkill.name;
		txt = activeSkill.text;
		if (nm == null || nm.Length == 0)
		{
			SetActiveSkillText(ref nm, ref txt);
		}
		if (txt == null || txt.Length == 0)
		{
			SetActiveSkillText(ref nm, ref txt);
		}
		return true;
	}

	public int GetActiveSkillSoul()
	{
		if (activeSkill == null)
		{
			return 0;
		}
		return activeSkill.soul;
	}

	public bool GetPanelSkillNameDesc(ref string nm, ref string txt)
	{
		if (panelSkill == null)
		{
			SetPanelSkillText(ref nm, ref txt);
			return false;
		}
		nm = panelSkill.name;
		txt = panelSkill.text;
		if (nm == null || nm.Length == 0)
		{
			SetPanelSkillText(ref nm, ref txt);
		}
		if (txt == null || txt.Length == 0)
		{
			SetPanelSkillText(ref nm, ref txt);
		}
		return true;
	}

	public int GetMaxBonus()
	{
		if (master != null)
		{
			return master.bonus_limit_base + bonus_limit;
		}
		return -1;
	}

	public int GetTotalBonus()
	{
		return bonus_life + bonus_attack + bonus_heal;
	}

	public void SetMasterRecord()
	{
		isHelper = false;
		if (unit_id <= 0)
		{
			master = ClientData.dummyUnitMaster;
			activeSkill = null;
			partySkill = null;
			return;
		}
		master = ClientData.GetUnitMasterRecord(unit_id);
		activeSkill = ClientData.GetActiveSkillMaster(master, level);
		partySkill = ClientData.GetPartySkillMaster(master, level);
		panelSkill = ClientData.GetPanelSkillMaster(master, level);
		if (master != null)
		{
			double y = GlobalDefines.UnitParam_CategoryPer[master.category - 1];
			int num = (master.style - 1) * 3;
			double y2 = GlobalDefines.UnitParam_StylePer[num];
			double y3 = GlobalDefines.UnitParam_StylePer[num + 1];
			double y4 = GlobalDefines.UnitParam_StylePer[num + 2];
			hp = (int)(Math.Pow(Math.Pow(level, y), y2) * (double)master.life);
			attack = (int)(Math.Pow(Math.Pow(level, y), y3) * (double)master.attack);
			heal = (int)(Math.Pow(Math.Pow(level, y), y4) * (double)master.heal);
			GlobalParamsMaster globalParamsMasterRecord = ClientData.GetGlobalParamsMasterRecord(1000);
			if (globalParamsMasterRecord != null)
			{
				hp += globalParamsMasterRecord.val * bonus_life;
			}
			globalParamsMasterRecord = ClientData.GetGlobalParamsMasterRecord(1001);
			if (globalParamsMasterRecord != null)
			{
				attack += globalParamsMasterRecord.val * bonus_attack;
			}
			globalParamsMasterRecord = ClientData.GetGlobalParamsMasterRecord(1002);
			if (globalParamsMasterRecord != null)
			{
				heal += globalParamsMasterRecord.val * bonus_heal;
			}
		}
	}

	public int GetNextLevelExp()
	{
		return GetLevelExp(level) - GetLevelExp(level - 1);
	}

	public int GetNextLevelExp(ref float per)
	{
		int num = 0;
		if (master == null)
		{
			per = 0f;
			num = 4649;
		}
		if (level == master.lv_max || master.category < 1 || master.category > 6)
		{
			num = 0;
		}
		else
		{
			int num2 = master.category - 1;
			per = (float)(Math.Pow(level, GlobalDefines.UnitParam_NextExp_Per[num2]) * (double)(float)master.grow);
			num = (int)per;
			if (per > 0f)
			{
				per = (float)exp / per;
				if (per > 1f)
				{
					per = 1f;
				}
			}
			if (num == 0)
			{
				DebugLogger.Log(">Not Found????");
				num = 1000;
			}
		}
		return num;
	}

	public int GetLevelExp(int lv)
	{
		if (master == null)
		{
			return 0;
		}
		int num = 0;
		float num2 = (float)(Math.Pow((float)lv, GlobalDefines.UnitParam_NextExp_Per[master.category - 1]) * (double)(float)master.grow);
		return (int)num2;
	}

	public int UnionPoint()
	{
		int num = 0;
		if (unit_id == 50000)
		{
			return total_exp;
		}
		return (int)((float)master.mix * Mathf.Pow(level, 0.5f));
	}

	public int UnitEvoPoint()
	{
		int num = 0;
		int set_pt = master.set_pt;
		return (int)((float)(level - 1) * Mathf.Pow(set_pt, 0.5f) + (float)set_pt);
	}

	public int NextEvoPoint()
	{
		return master.need_pt;
	}

	public void SetLevelData(int id, int lv)
	{
		unit_id = id;
		level = lv;
		user_id = 0u;
		instance_id = 0uL;
		member_id = 0;
		exp = 0;
		activeSkill = null;
		partySkill = null;
		SetMasterRecord();
	}

	public bool IsLeader()
	{
		return instance_id == ClientData.m_PartyInfo.GetLeaderInstanceID();
	}
}

